#[using="LK M CLI HLlo HLhi g FS"] Lemma art_rng_shadow_allowed : forall sp scr b n a, 0 <= b ->
  (forall i, 0 <= i < n -> cls sp scr (b + i)) ->
  (b + n <= BIGSHADOW_LO \/ BIGSHADOW_HI <= b) -> b + n <= 2 ^ 47 ->
